    const result = await inspectPublicMcp("https://mcp.example.com/mcp", "streamable-http");
    expect(result).toMatchObject({
      status: "available",
      name: "Example",
      protocolVersion: "2025-03-26",
    });
    expect(JSON.stringify(result)).not.toContain("never expose me");
    expect(request.mock.calls[0][2].headers).not.toHaveProperty("Authorization");
  });
  it("bounds responses and rejects unrelated JSON", async () => {
    request
      .mockResolvedValueOnce(new Response("x".repeat(65 * 1024)))
      .mockResolvedValueOnce(Response.json({ status: "healthy" }));
    expect((await inspectPublicMcp("https://mcp.example.com", "streamable-http")).status).toBe(
      "unavailable",
    );
    expect((await inspectPublicMcp("https://mcp.example.com", "streamable-http")).status).toBe(
      "unavailable",
    );
  });
  it("does not follow redirects, private URLs, or SSE session endpoints", async () => {
    request.mockResolvedValueOnce(
      new Response(null, { status: 302, headers: { Location: "http://localhost/" } }),
    );
    expect((await inspectPublicMcp("https://mcp.example.com", "streamable-http")).status).toBe(
      "unavailable",
    );
    expect((await inspectPublicMcp("https://127.0.0.1", "streamable-http")).status).toBe(
      "unavailable",
    );
    request.mockResolvedValueOnce(
      new Response("event: endpoint\ndata: http://localhost/private\n\n", {
        headers: { "content-type": "text/event-stream" },
      }),
    );
    expect((await inspectPublicMcp("https://mcp.example.com/sse", "sse")).status).toBe("available");
    expect(request).toHaveBeenCalledTimes(2);
  });
  it("distinguishes OAuth discovery from a successful client registration or sign-in", async () => {
    request
      .mockResolvedValueOnce(
        new Response(null, {
          status: 401,
          headers: {
            "WWW-Authenticate":
              'Bearer resource_metadata="https://mcp.example.com/.well-known/oauth-protected-resource"',
          },
        }),
      )
      .mockResolvedValueOnce(Response.json({ authorization_servers: ["https://auth.example.com"] }))
      .mockResolvedValueOnce(
        Response.json({
          issuer: "https://auth.example.com",
          authorization_endpoint: "https://auth.example.com/authorize",
          token_endpoint: "https://auth.example.com/token",
          registration_endpoint: "https://auth.example.com/register",
          code_challenge_methods_supported: ["S256"],
        }),
      );
    expect(
      await inspectPublicMcp("https://mcp.example.com/mcp", "streamable-http", true),
    ).toMatchObject({ status: "authentication-required", oauthDiscovery: "ready" });
    expect(request.mock.calls.slice(1).every((call) => !call[2].body)).toBe(true);
  });
  it("does not treat a 401 as compatible OAuth discovery", async () => {
    request.mockImplementation(async () => new Response(null, { status: 401 }));
    expect(
      await inspectPublicMcp("https://mcp.example.com", "streamable-http", true),
    ).toMatchObject({ status: "authentication-required", oauthDiscovery: "unavailable" });
  });
});

"use node";

import { assertManagedMcpUrl } from "clawhub-schema";
import { requestPublicResource } from "../../server/og/requestPublicImage";

export type McpPublicInspection = {
  status: "available" | "authentication-required" | "unavailable";
  observedAt: number;
  name?: string;
  version?: string;
  protocolVersion?: string;
  oauthDiscovery?: "ready" | "unavailable";
};

const MAX_BYTES = 64 * 1024;

async function readJson(response: Response): Promise<Record<string, unknown>> {
  const reader = response.body?.getReader();
  if (!reader) throw new Error("Empty response");
  const sse = response.headers.get("content-type")?.includes("text/event-stream");
  let text = "";
  let size = 0;
  const decoder = new TextDecoder();
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > MAX_BYTES) throw new Error("Response too large");
      text += decoder.decode(value, { stream: true });
      if (sse) {
        // Ignore keepalives and notifications, including CRLF-delimited streams.
        for (;;) {
          const boundary = /\r?\n\r?\n/.exec(text);
          if (!boundary) break;
          const frame = text.slice(0, boundary.index);
          text = text.slice(boundary.index + boundary[0].length);
          const data = frame
            .split(/\r?\n/)
            .filter((line) => line.startsWith("data:"))
            .map((line) => line.slice(5).trimStart())
            .join("\n");
          if (!data) continue;
          const body = JSON.parse(data) as Record<string, unknown>;
          if (body.id === 1) return body;
        }
      }
    }
    if (sse) throw new Error("Missing initialize response");
    return JSON.parse(text + decoder.decode()) as Record<string, unknown>;
  } finally {
    await reader.cancel().catch(() => {});
  }
}

async function requestJson(url: string, signal: AbortSignal) {
  assertManagedMcpUrl(url);
  const response = await requestPublicResource(new URL(url), signal, {
    headers: { Accept: "application/json", "User-Agent": "ClawHub/1.0 MCP-compatibility-check" },
  });
  if (!response.ok) {
    await response.body?.cancel();
    throw new Error("Metadata unavailable");
  }
  const json = await readJson(response);
  if (!json || typeof json !== "object" || Array.isArray(json)) throw new Error("Invalid metadata");
  return json;
}

function wellKnown(url: URL, kind: string) {
  return `${url.origin}/.well-known/${kind}${url.pathname === "/" ? "" : url.pathname}`;
}

async function discoverOAuth(endpoint: string, challenge: string | null, signal: AbortSignal) {
  const url = new URL(endpoint);
  const advertised = /(?:^|[\s,])resource_metadata="([^"]+)"/i.exec(challenge ?? "")?.[1];
  const candidates = [
    ...new Set(
      [
        advertised,
        wellKnown(url, "oauth-protected-resource"),
        `${url.origin}/.well-known/oauth-protected-resource`,
      ].filter((value): value is string => Boolean(value)),
    ),
  ];
  let issuer = url.origin;
  for (const candidate of candidates) {
    try {
      const resource = await requestJson(candidate, signal);
      if (
        Array.isArray(resource.authorization_servers) &&
        typeof resource.authorization_servers[0] === "string"
      ) {
        issuer = resource.authorization_servers[0];
        break;
      }
    } catch {
      /* Legacy servers can advertise authorization metadata without resource metadata. */
    }
  }
  assertManagedMcpUrl(issuer);
  const issuerUrl = new URL(issuer);
  for (const candidate of new Set([
    wellKnown(issuerUrl, "oauth-authorization-server"),
    `${issuer.replace(/\/$/, "")}/.well-known/openid-configuration`,
  ])) {
    try {
      const metadata = await requestJson(candidate, signal);
      if (
        typeof metadata.issuer !== "string" ||
        metadata.issuer.replace(/\/$/, "") !== issuer.replace(/\/$/, "")
      )
        continue;
      for (const key of ["authorization_endpoint", "token_endpoint", "registration_endpoint"]) {
        if (typeof metadata[key] !== "string") throw new Error("Missing OAuth endpoint");
        assertManagedMcpUrl(metadata[key]);
      }
      if (
        Array.isArray(metadata.code_challenge_methods_supported) &&
        !metadata.code_challenge_methods_supported.includes("S256")
      )
        continue;
      return true;
    } catch {
      /* Try the standard discovery fallback, without following redirects. */
    }
  }
  return false;
}

/** Bounded public observation. OAuth discovery does not register a client or prove account access. */
export async function inspectPublicMcp(
  url: string,
  transport: "streamable-http" | "sse",
  checkOAuth = false,
): Promise<McpPublicInspection> {
  const observedAt = Date.now();
  const unavailable = { status: "unavailable" as const, observedAt };
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), checkOAuth ? 15_000 : 8000);
  let response: Response | undefined;
  try {
    assertManagedMcpUrl(url);
    response = await requestPublicResource(new URL(url), controller.signal, {
      headers: {
        Accept: "application/json, text/event-stream",
        "User-Agent": "ClawHub/1.0 MCP-compatibility-check",
        ...(transport === "streamable-http" ? { "Content-Type": "application/json" } : {}),
      },
      ...(transport === "streamable-http"
        ? {
            body: JSON.stringify({
              jsonrpc: "2.0",
              id: 1,
              method: "initialize",
              params: {
                protocolVersion: "2025-03-26",
                capabilities: {},
                clientInfo: { name: "clawhub-public-preview", version: "1.0.0" },
              },
            }),
          }
        : {}),
    });
    const challenge = response.headers.get("www-authenticate");
    let result: McpPublicInspection = unavailable;
    // A 403 can be a WAF/policy denial, not a usable sign-in challenge. Fail closed
    // for authoring; saved plugin details remain viewable when inspection fails.
    if (response.status === 401) result = { status: "authentication-required", observedAt };
    else if (response.ok && transport === "sse") {
      // Never follow the advertised session endpoint during a public preview.
      if (response.headers.get("content-type")?.includes("text/event-stream"))
        result = { status: "available", observedAt };
    } else if (response.ok) {
      const body = await readJson(response);
      if (
        body.jsonrpc === "2.0" &&
        body.id === 1 &&
        body.result &&
        typeof body.result === "object"
      ) {
        const initialized = body.result as Record<string, unknown>;
        const info =
          initialized.serverInfo && typeof initialized.serverInfo === "object"
            ? (initialized.serverInfo as Record<string, unknown>)
            : {};
        const short = (value: unknown) =>
          typeof value === "string"
            ? value
                .slice(0, 120)
                .split("")
                .filter((character) => character.charCodeAt(0) >= 32)
                .join("")
            : undefined;
        if (short(initialized.protocolVersion) && short(info.name))
          result = {
            status: "available",
            observedAt,
            name: short(info.name),
            version: short(info.version),
            protocolVersion: short(initialized.protocolVersion),
          };
      }
    }
    if (response.body && !response.body.locked) await response.body.cancel().catch(() => {});
    if (checkOAuth)
      result.oauthDiscovery = (await discoverOAuth(url, challenge, controller.signal))
        ? "ready"
        : "unavailable";
    return result;
  } catch {
    return { ...unavailable, ...(checkOAuth ? { oauthDiscovery: "unavailable" as const } : {}) };
  } finally {
    clearTimeout(timeout);
    controller.abort();
    if (response?.body && !response.body.locked) await response.body.cancel().catch(() => {});
  }
}

name: Security Scan Codex Worker

on:
  repository_dispatch:
    types: [clawhub-security-scan]
  workflow_dispatch:
    inputs:
      environment:
        description: "Deployment to scan; Test requires exact revision and at most three assigned jobs"
        type: choice
        options: [Production, Test]
        default: Production
      expected-sha:
        description: "Exact deployed revision required for a Test scan"
        required: false
        default: ""
      limit:
        description: "Deprecated alias for batch-limit"
        required: false
        default: ""
      batch-limit:
        description: "Maximum Codex scans to run in parallel per worker shard"
        required: true
        default: "4"
      assigned-jobs:
        description: "Optional JSON of disjoint bulk skill job ID arrays, one per shared worker"
        required: false
        default: ""
      shared-workers:
        description: "Shared machines for assigned jobs; drain the old pool before changing"
        type: choice
        options: ["9", "18"]
        default: "9"
      max-jobs:
        description: "Optional total jobs cap per worker shard"
        required: false
        default: ""
      max-runtime-minutes:
        description: "Stop claiming new jobs after this many minutes"
        required: true
        default: "12"
permissions:
  contents: read
  packages: read

jobs:
  dispatch-staging:
    if: >-
      github.repository == 'openclaw/clawhub' &&
      github.event_name == 'repository_dispatch' &&
      github.event.client_payload.environment == 'staging'
    runs-on: ubuntu-latest
    timeout-minutes: 5
    permissions:
      actions: write
    steps:
      - name: Dispatch staging worker
        env:
          GH_TOKEN: ${{ github.token }}
          BATCH_LIMIT: ${{ github.event.client_payload.batch_limit || '2' }}
          MAX_RUNTIME_MINUTES: ${{ github.event.client_payload.max_runtime_minutes || '12' }}
        run: |
          set -euo pipefail
          gh workflow run security-scan-codex.yml --repo openclaw/clawhub --ref staging \
            -f batch-limit="$BATCH_LIMIT" \
            -f max-runtime-minutes="$MAX_RUNTIME_MINUTES"

  codex-security-scan:
    if: >-
      github.repository == 'openclaw/clawhub' &&
      ((github.event_name == 'repository_dispatch' &&
        github.ref == 'refs/heads/main' &&
        (!github.event.client_payload.environment || github.event.client_payload.environment == 'Production')) ||
       (github.event_name == 'workflow_dispatch' &&
        ((inputs.environment == 'Test' &&
          (github.ref == 'refs/heads/main' ||
           (github.ref == 'refs/heads/codex/endor-plugin-scan-main-20261001' && github.actor == 'Patrick-Erichsen'))) ||
         (inputs.environment == 'Production' && github.ref == 'refs/heads/main'))))
    name: Codex security scan ${{ matrix.lane }} shard ${{ matrix.shard }}
    runs-on: blacksmith-16vcpu-ubuntu-2404
    timeout-minutes: 60
    environment: ${{ inputs.environment || 'Production' }}
    concurrency:
      # Bulk assignments must not wait behind ordinary queue workers on the same shard.
      # Priority remains one reserved lane shared by every dispatch mode.
      group: ${{ inputs.environment == 'Test' && 'deploy-test' || format('clawhub-security-scan-{0}{1}', matrix.lane == 'shared' && inputs['assigned-jobs'] && 'assigned-' || '', matrix.shard) }}
      cancel-in-progress: false
    strategy:
      fail-fast: false
      max-parallel: 19
      matrix:
        lane: [shared]
        shard: ${{ fromJSON(inputs.environment == 'Test' && '["shared-0"]' || inputs['assigned-jobs'] && inputs['shared-workers'] == '18' && '["shared-0","shared-1","shared-2","shared-3","shared-4","shared-5","shared-6","shared-7","shared-8","shared-9","shared-10","shared-11","shared-12","shared-13","shared-14","shared-15","shared-16","shared-17"]' || '["shared-0","shared-1","shared-2","shared-3","shared-4","shared-5","shared-6","shared-7","shared-8"]') }}
        include: ${{ fromJSON(inputs.environment == 'Test' && '[]' || '[{"lane":"priority","shard":"priority-0"}]') }}
    env:
      CONVEX_URL: ${{ vars.CONVEX_URL || vars.VITE_CONVEX_URL || 'https://wry-manatee-359.convex.cloud' }}
      CODEX_SECURITY_SCAN_LIMIT: ${{ github.event.client_payload.batch_limit || inputs.limit || inputs['batch-limit'] || '4' }}
      CODEX_SECURITY_SCAN_MAX_JOBS: ${{ github.event.client_payload.max_jobs || inputs['max-jobs'] || '' }}
      CODEX_SECURITY_SCAN_MAX_RUNTIME_MINUTES: ${{ github.event.client_payload.max_runtime_minutes || inputs['max-runtime-minutes'] || '12' }}
      CODEX_SECURITY_SCAN_SHARED_WORKERS: ${{ inputs['shared-workers'] || '9' }}
      CODEX_SECURITY_SCAN_ASSIGNED_JOBS: ${{ inputs['assigned-jobs'] || '' }}
      CODEX_SECURITY_SCAN_LANE: ${{ matrix.lane }}
      CODEX_SECURITY_SCAN_CLAWSCAN_TIMEOUT_MS: ${{ vars.CODEX_SECURITY_SCAN_CLAWSCAN_TIMEOUT_MS || '900000' }}
      CODEX_SECURITY_SCAN_ENDOR_ENABLED: ${{ vars.CODEX_SECURITY_SCAN_ENDOR_ENABLED || '0' }}
      CODEX_SECURITY_SCAN_ENDOR_PACKAGES: ${{ vars.CODEX_SECURITY_SCAN_ENDOR_PACKAGES }}
      CODEX_SECURITY_SCAN_ENDOR_JUDGE_ENABLED: ${{ vars.CODEX_SECURITY_SCAN_ENDOR_JUDGE_ENABLED || '0' }}
      CODEX_SECURITY_SCAN_ENDOR_IMAGE: ${{ vars.CODEX_SECURITY_SCAN_ENDOR_IMAGE }}
      # The runner is disposable and installs the reviewed, source-pinned host scanners below.
      CODEX_SECURITY_SCAN_CLAWSCAN_SANDBOX: "off"
      CODEX_SECURITY_SCAN_LEASE_MINUTES: "60"
      CODEX_SECURITY_SCAN_DIAGNOSTICS_DIR: codex-security-scan-diagnostics-${{ matrix.shard }}
      CODEX_SECURITY_SCAN_SHARD: ${{ matrix.shard }}
      CODEX_SECURITY_SCAN_WORKER_ID: "github-actions:${{ github.run_id }}:${{ github.run_attempt }}:${{ matrix.shard }}"
      SKILLSPECTOR_PROVIDER: openai
    steps:
      - uses: actions/checkout@v7.0.1

      - name: Check Test scan target
        id: test-target
        if: inputs.environment == 'Test'
        env:
          EXPECTED_SHA: ${{ inputs['expected-sha'] }}
          SELECTED_SHA: ${{ github.sha }}
          SELECTED_REF: ${{ github.ref }}
          SELECTED_ACTOR: ${{ github.actor }}
          CONVEX_DEPLOY_KEY: ${{ secrets.CONVEX_DEPLOY_KEY }}
        run: |
          set -euo pipefail
          shopt -s nocasematch
          [[ "$SELECTED_REF" == refs/heads/main || ( "$SELECTED_REF" == refs/heads/codex/endor-plugin-scan-main-20261001 && "$SELECTED_ACTOR" == Patrick-Erichsen ) ]] || exit 1
          [[ "$EXPECTED_SHA" =~ ^[a-f0-9]{40}$ && "$EXPECTED_SHA" == "$SELECTED_SHA" ]] || exit 1
          [[ "$CONVEX_URL" == https://academic-chihuahua-392.convex.cloud ]] || exit 1
          [[ "$CONVEX_DEPLOY_KEY" == prod:academic-chihuahua-392\|* ]] || exit 1
          [[ "$CODEX_SECURITY_SCAN_SHARED_WORKERS" == 9 && "$CODEX_SECURITY_SCAN_MAX_JOBS" == 3 ]] || exit 1

      - uses: ./.github/actions/setup-bun

      - name: Prepare Test scan authentication
        id: test-auth
        if: inputs.environment == 'Test'
        env:
          CONVEX_DEPLOY_KEY: ${{ secrets.CONVEX_DEPLOY_KEY }}
        run: |
          set -euo pipefail
          bun - <<'JS'
          import { spawnSync } from "node:child_process";
          import { readWorkerAssignment } from "./packages/clawhub-admin/src/scanAssignments.ts";
          const raw = process.env.CODEX_SECURITY_SCAN_ASSIGNED_JOBS;
          const ids = readWorkerAssignment(raw, "shared", "shared-0", 9);
          if (!ids?.length || ids.length > 3 || Array.from({length: 8}, (_, i) => readWorkerAssignment(raw, "shared", "shared-" + (i + 1), 9)?.length).some(Boolean)) {
            throw new Error("Test requires 1–3 assigned jobs on shared-0 only");
          }
          for (const jobId of ids) {
            const result = spawnSync("bunx", ["convex", "run", "securityScan:getJobTargetInternal", JSON.stringify({jobId}), "--prod"], {encoding: "utf8"});
            if (result.status !== 0) throw new Error("Cannot read assigned Test plugin job");
            const target = JSON.parse(result.stdout);
            if (target?.job?.targetKind !== "packageRelease" || !target.release || !["code-plugin", "bundle-plugin"].includes(target.package?.family) ||
                target.job.status !== "queued" || target.job.source !== "bulk-rescan" || target.job.rolloutGate ||
                typeof target.job.nextRunAt !== "number" || target.job.nextRunAt > Date.now()) {
              throw new Error("Test assignments must be ready, ungated, queued native plugin bulk jobs");
            }
          }
          JS
          printf 'ENDOR_TEST_STARTED_AT=%s\n' "$(date +%s000)" >> "$GITHUB_ENV"
          [[ "$(bunx convex env get APP_BUILD_SHA --prod)" == "$GITHUB_SHA" ]]
          worker_token="$(bunx convex env get SECURITY_SCAN_WORKER_TOKEN --prod)"
          [[ -n "$worker_token" ]] || { echo 'Test SECURITY_SCAN_WORKER_TOKEN is missing' >&2; exit 1; }
          printf '::add-mask::%s\n' "$worker_token"
          printf 'token=%s\n' "$worker_token" >> "$GITHUB_OUTPUT"

      - name: Build Endor scanner for Test
        if: inputs.environment == 'Test'
        run: |
          set -euo pipefail
          curl --fail --location --retry 3 https://api.endorlabs.com/download/endorlabs/v1.7.1115/binaries/endorctl_v1.7.1115_linux_amd64 --output scripts/security/endor/endorctl
          docker build --platform linux/amd64 --build-arg ENDORCTL_SHA256=4022e91a39d04f852f8a6195a5f98297af6cf2738f4012b1591bc87976136d4b --tag "clawhub-endor-test:$GITHUB_SHA" scripts/security/endor
          image="$(docker image inspect --format '{{.Id}}' "clawhub-endor-test:$GITHUB_SHA")"
          [[ "$image" =~ ^sha256:[a-f0-9]{64}$ ]]
          sh scripts/security/check-endor-image.sh "$image"
          printf 'CODEX_SECURITY_SCAN_ENDOR_IMAGE=%s\nCODEX_SECURITY_SCAN_ENDOR_ENABLED=1\n' "$image" >> "$GITHUB_ENV"

      - uses: actions/setup-python@v7
        with:
          python-version: "3.12"

      - name: Install Codex CLI
        run: |
          set -euo pipefail
          npm install -g @openai/codex@0.160.0
          codex --version

      - name: Install ClawScan CLI
        run: |
          set -euo pipefail
          sh scripts/security/install-clawscan.sh

      - name: Prepare Endor scanner
        if: ${{ inputs.environment != 'Test' && env.CODEX_SECURITY_SCAN_ENDOR_ENABLED == '1' }}
        env:
          GH_TOKEN: ${{ github.token }}
        run: |
          set -euo pipefail
          [[ "$CODEX_SECURITY_SCAN_ENDOR_IMAGE" =~ @sha256:[a-f0-9]{64}$ ]] || { echo 'Endor requires a Docker image pinned by SHA-256 digest'; exit 1; }
          export DOCKER_CONFIG
          DOCKER_CONFIG=$(mktemp -d)
          trap 'rm -rf "$DOCKER_CONFIG"' EXIT
          printf '%s' "$GH_TOKEN" | docker login ghcr.io --username "$GITHUB_ACTOR" --password-stdin
          docker pull "$CODEX_SECURITY_SCAN_ENDOR_IMAGE"
          docker run --rm --network none "$CODEX_SECURITY_SCAN_ENDOR_IMAGE" test -x /usr/local/bin/clawhub-endor-scan

      - name: Install A.I.G scanner
        run: |
          set -euo pipefail
          sh scripts/security/install-clawscan-scanners.sh aig

      - name: Install SkillSpector
        run: |
          set -euo pipefail
          sh scripts/security/install-clawscan-scanners.sh skillspector

      - name: Authenticate Codex CLI
        env:
          OPENAI_API_KEY: ${{ secrets.OPENAI_API_KEY }}
        run: printf '%s' "$OPENAI_API_KEY" | codex login --with-api-key

      - name: Run Codex security worker
        env:
          CODEX_API_KEY: ${{ secrets.CODEX_API_KEY || secrets.OPENAI_API_KEY }}
          DEFAULT_BASE_URL: https://api.openai.com/v1
          DEFAULT_MODEL: ${{ vars.DEFAULT_MODEL || 'gpt-6.1-sol' }}
          REASONING_EFFORT: ${{ vars.REASONING_EFFORT || 'medium' }}
          SKILLSPECTOR_MODEL: ${{ vars.SKILLSPECTOR_MODEL || 'gpt-6.1-sol' }}
          SKILLSPECTOR_REASONING_EFFORT: ${{ vars.SKILLSPECTOR_REASONING_EFFORT || 'medium' }}
          LLM_API_KEY: ${{ secrets.OPENAI_API_KEY || secrets.CODEX_API_KEY }}
          OPENAI_API_KEY: ${{ secrets.OPENAI_API_KEY }}
          SECURITY_SCAN_WORKER_TOKEN: ${{ steps.test-auth.outputs.token || secrets.SECURITY_SCAN_WORKER_TOKEN }}
          ENDOR_NAMESPACE: ${{ vars.ENDOR_NAMESPACE }}
          ENDOR_API: ${{ vars.ENDOR_API }}
          ENDOR_API_CREDENTIALS_KEY: ${{ secrets.ENDOR_API_CREDENTIALS_KEY }}
          ENDOR_API_CREDENTIALS_SECRET: ${{ secrets.ENDOR_API_CREDENTIALS_SECRET }}
        run: |
          bun scripts/security/run-codex-scan-worker.ts \
            --batch-limit "$CODEX_SECURITY_SCAN_LIMIT" \
            --lane "$CODEX_SECURITY_SCAN_LANE" \
            --max-jobs "$CODEX_SECURITY_SCAN_MAX_JOBS" \
            --max-runtime-minutes "$CODEX_SECURITY_SCAN_MAX_RUNTIME_MINUTES" \
            --lease-minutes "$CODEX_SECURITY_SCAN_LEASE_MINUTES"

      - name: Verify Test scan results
        if: inputs.environment == 'Test'
        env:
          CONVEX_DEPLOY_KEY: ${{ secrets.CONVEX_DEPLOY_KEY }}
        run: |
          set -euo pipefail
          bun - <<'JS'
          import { spawnSync } from "node:child_process";
          import { readWorkerAssignment } from "./packages/clawhub-admin/src/scanAssignments.ts";
          const ids = readWorkerAssignment(process.env.CODEX_SECURITY_SCAN_ASSIGNED_JOBS, "shared", "shared-0", 9);
          if (!ids?.length || ids.length > 3) throw new Error("Test requires 1–3 assigned jobs");
          const startedAt = Number(process.env.ENDOR_TEST_STARTED_AT);
          if (!Number.isFinite(startedAt) || startedAt <= 0) throw new Error("Test scan start time is missing");
          function read(name, args) {
            const result = spawnSync("bunx", ["convex", "run", name, JSON.stringify(args), "--prod"], {encoding: "utf8"});
            if (result.status !== 0) throw new Error("Cannot read assigned Test scan result");
            return JSON.parse(result.stdout);
          }
          for (const jobId of ids) {
            const target = read("securityScan:getJobTargetInternal", {jobId});
            const job = target?.job;
            // A malicious verdict quarantines the release, hiding it from getJobTargetInternal.
            const release = job?.packageReleaseId && read("packages:getReleaseByIdInternal", {releaseId: job.packageReleaseId});
            if (job?.status !== "succeeded" || job.targetKind !== "packageRelease" || job.workerId !== process.env.CODEX_SECURITY_SCAN_WORKER_ID ||
                job.runId !== process.env.GITHUB_RUN_ID || job.leaseToken || job.leaseExpiresAt || !(job.completedAt >= startedAt) ||
                release?.endorAnalysis?.status !== "completed" || !(release.endorAnalysis.checkedAt >= startedAt) ||
                !(release.llmAnalysis?.checkedAt >= startedAt)) {
              throw new Error("Assigned Test plugin has no completed Endor and judge results from this worker");
            }
            console.log(JSON.stringify({version: release.version, reachableFunctions: release.endorAnalysis.reachableFunctionCount, verdict: release.llmAnalysis.verdict}));
          }
          JS

      - name: Prepare Codex security diagnostics scan
        if: ${{ !cancelled() }}
        run: mkdir -p "$CODEX_SECURITY_SCAN_DIAGNOSTICS_DIR"

      - name: Scan Codex security diagnostics for verified secrets
        id: diagnostics_secret_scan
        if: ${{ !cancelled() }}
        run: |
          docker run --rm \
            -v "$PWD/$CODEX_SECURITY_SCAN_DIAGNOSTICS_DIR:/scan:ro" \
            ghcr.io/trufflesecurity/trufflehog:3.95.5@sha256:56c25710275c4b8d74c4f1346a5e7c606fa7ff4afe996f680b288d0fae3fcd9c \
            filesystem /scan \
            --only-verified \
            --fail \
            --no-update \
            --github-actions

      - name: Upload Codex security diagnostics
        if: ${{ !cancelled() && steps.diagnostics_secret_scan.outcome == 'success' }}
        uses: actions/upload-artifact@v7
        with:
          name: codex-security-scan-diagnostics-${{ github.run_id }}-${{ matrix.shard }}
          path: ${{ env.CODEX_SECURITY_SCAN_DIAGNOSTICS_DIR }}
          if-no-files-found: ignore
